  photoPetraNight: ['Petra after sunset', 'البتراء بعد الغروب', 'Pétra après le coucher du soleil', 'Петра после заката', 'Petra tras la puesta de sol', 'Petra nach Sonnenuntergang', '日落后的佩特拉', 'Petra dopo il tramonto', '日没後のペトラ', 'Gün batımından sonra Petra'],
  photoViewer: ['Photo viewer', 'عارض الصور', 'Visionneuse photo', 'Просмотр фото', 'Visor de fotos', 'Fotobetrachter', '图片查看器', 'Visualizzatore foto', '写真ビューアー', 'Fotoğraf görüntüleyici'],
  viewPhoto: ['View photo', 'اعرض الصورة', 'Voir la photo', 'Посмотреть фото', 'Ver foto', 'Foto ansehen', '查看图片', 'Visualizza foto', '写真を見る', 'Fotoğrafı görüntüle'],
