export type TranslationKey = keyof typeof rows;
export type TranslationDictionary = Record<TranslationKey, string>;

export function getTranslations(language: Language): TranslationDictionary {
  const languageIndex = languages.indexOf(language);
  return Object.fromEntries(
    Object.entries(rows).map(([key, translations]) => [key, translations[languageIndex] || translations[0]]),
  ) as TranslationDictionary;
}

export function isLanguage(value: string): value is Language {
  return languages.includes(value as Language);
}
